fn collect_using(directive: &Node, source: &[u8], pending: &mut PendingFile, module_index: usize) {
    let line = line_of(directive);
    let Some(text) = node_text(directive, source) else {
        return;
    };
    let raw = text.trim().trim_end_matches(';').trim();
    // Strip leading `using` (and optional `static`).
    let after_using = raw.strip_prefix("using").unwrap_or(raw).trim_start();
    let after_static = after_using
        .strip_prefix("static ")
        .map(str::trim_start)
        .unwrap_or(after_using);
    // Alias form `Alias = Real.Namespace` — right side is the imported path.
    let path = if let Some((_, rhs)) = after_static.split_once('=') {
        rhs.trim()
    } else {
        after_static
    };
    if path.is_empty() {
        return;
    }
    let leaf = path.rsplit('.').next().unwrap_or(path).to_string();
    let to_path = Some(format!("{path}::*"));
    push_import(pending, module_index, leaf, to_path, line);
}

fn collect_annotations(decl: &Node, source: &[u8]) -> Option<String> {
    let mut names: Vec<String> = Vec::new();
    let mut cursor = decl.walk();
    for child in decl.children(&mut cursor) {
        if !matches!(child.kind(), "modifiers") {
            continue;
        }
        let mut mc = child.walk();
        for m in child.children(&mut mc) {
            match m.kind() {
                "annotation" | "marker_annotation" => {
                    if let Some(name_node) = m.child_by_field_name("name") {
                        let raw = node_text(&name_node, source).unwrap_or("").trim();
                        if !raw.is_empty() {
                            let leaf = raw.rsplit('.').next().unwrap_or(raw);
                            names.push(leaf.to_string());
                        }
                    }
                }
                _ => {}
            }
        }
    }
    if names.is_empty() {
        None
    } else {
        Some(format!(",{},", names.join(",")))
    }
}

fn collect_use(decl: &Node, source: &[u8], pending: &mut PendingFile, module_index: usize) {
    let line = line_of(decl);
    let Some(text) = node_text(decl, source) else {
        return;
    };
    let raw = text.trim().trim_end_matches(';').trim();
    let after_use = raw.strip_prefix("use").unwrap_or(raw).trim_start();
    // Skip optional `function ` / `const `.
    let body = after_use
        .strip_prefix("function ")
        .or_else(|| after_use.strip_prefix("const "))
        .unwrap_or(after_use);

    // Grouped form: `Foo\Bar\{A, B as C}`.
    if let Some(brace) = body.find('{') {
        let prefix = body[..brace].trim().trim_end_matches('\\').trim();
        let inside = body[brace + 1..].trim_end_matches('}').trim();
        for item in inside.split(',') {
            emit_use_item(item.trim(), Some(prefix), pending, module_index, line);
        }
    } else {
        emit_use_item(body, None, pending, module_index, line);
    }
}

fn emit_use_item(
    item: &str,
    prefix: Option<&str>,
    pending: &mut PendingFile,
    module_index: usize,
    line: u32,
) {
    if item.is_empty() {
        return;
    }
    let (raw_path, alias) = if let Some((p, a)) = item.split_once(" as ") {
        (p.trim(), Some(a.trim()))
    } else {
        (item, None)
    };
    let full_path = match prefix {
        Some(p) => format!("{p}\\{raw_path}"),
        None => raw_path.to_string(),
    };
    let leaf = alias.map(str::to_string).unwrap_or_else(|| {
        full_path
            .rsplit('\\')
            .next()
            .unwrap_or(&full_path)
            .to_string()
    });
    push_import(pending, module_index, leaf, Some(full_path), line);
}

